using CLV_CivilTools.Ufls;
using System.Globalization;
using XY=CLV_CivilTools.Ufls.PipeStakeMath.XY;
int count=0;
void Check(bool yes,string message){if(!yes)throw new Exception(message);count++;}
void Near(double x,double y,string message)=>Check(Math.Abs(x-y)<1e-7,message);
void Reject(Action action,string message){try{action();}catch(ArgumentException){count++;return;}throw new Exception(message);}
var line=PipeStakeMath.Line(new(0,0),new(100,0),new(50,20.07));
Near(line.Fraction,0.5,"line fraction");Near(line.Along,50,"line station");Near(line.Offset,20.07,"shot offset");Check(!line.Clamped,"normal shot not clamped");
var outside=PipeStakeMath.Line(new(0,0),new(100,0),new(110,20));
Check(outside.Clamped,"endpoint warning");Near(outside.Fraction,1,"clamp end");Near(outside.Offset,Math.Sqrt(500),"distance to end, not perpendicular offset");
double s=120/Math.Sqrt(2);
var arc=PipeStakeMath.Arc(new(100,0),new(0,100),new(0,0),false,Math.PI/2,new(s,s));
Near(arc.Offset,20,"arc offset");Near(arc.Fraction,0.5,"arc fraction");Near(arc.Along,25*Math.PI,"arc length, not chord");Check(!arc.Clamped,"arc not clamped");
var cw=PipeStakeMath.Arc(new(100,0),new(0,-100),new(0,0),true,Math.PI/2,new(s,-s));Near(cw.Fraction,.5,"clockwise arc");
var reverse=PipeStakeMath.Arc(new(0,100),new(100,0),new(0,0),true,Math.PI/2,new(s,s));Near(reverse.Fraction,.5,"reversed endpoints");
double angle=10*Math.PI/180;
var wrap=PipeStakeMath.Arc(new(100*Math.Cos(angle),-100*Math.Sin(angle)),new(100*Math.Cos(angle),100*Math.Sin(angle)),new(0,0),false,2*angle,new(120,0));Near(wrap.Fraction,.5,"arc crosses angle zero");
var arcEnd=PipeStakeMath.Arc(new(100,0),new(0,100),new(0,0),false,Math.PI/2,new(-20,120));Check(arcEnd.Clamped,"outside arc sweep");Near(arcEnd.Fraction,1,"nearest arc endpoint");
var elevations=PipeStakeMath.Elevations(2330.710,2330.710,6,11.0/12,0.5);
Near(elevations.Invert,2327.710,"native centerline to invert");Near(elevations.Top!.Value,2334.626666666667,"outside roof with eleven-inch wall");
Check(PipeStakeMath.Elevations(100,90,6,null,.5).Top==null,"missing wall does not become zero");
Check(PipeStakeMath.Elevations(100,90,6,0,.5).Top==null,"zero wall unknown");
Reject(()=>PipeStakeMath.Line(new(0,0),new(0,0),new(1,1)),"zero length");
Reject(()=>PipeStakeMath.Line(new(0,0),new(1,0),new(double.NaN,1)),"nonfinite pick");
Reject(()=>PipeStakeMath.Arc(new(100,0),new(0,100),new(0,0),false,Math.PI/2,new(0,0)),"center ambiguity");
Reject(()=>PipeStakeMath.Arc(new(100,0),new(0,100),new(0,0),false,Math.PI/2,new(-120,-120)),"equal endpoint ambiguity");
Reject(()=>PipeStakeMath.Arc(new(100,0),new(0,100),new(0,0),true,Math.PI/2,new(120,0)),"arc orientation mismatch");
Reject(()=>PipeStakeMath.Elevations(100,90,0,1,.5),"invalid native height");
var v=new PipeStakeMath.LabelValues("POINT 10007","P{\\C1;bad}","10.000 ft W x 6.000 ft H","RCB",2327.710,2334.626666666667,11.0/12,20.07,803.32,false,"SD","128+10.27",null);
CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("fr-FR");string label=PipeStakeMath.Label(v);
Check(label.Contains("PIPE STA [SD]: 128+10.27"),"native formatted alignment station");
Check(label.Contains("OFFSET FROM PIPE CL: 20.07 ft"),"culture invariant offset");
Check(!label.Contains("SLOPE")&&!label.Contains("START INVERT")&&!label.Contains("END INVERT"),"omit unrequested fields");
Check(label.Contains("P\\{\\\\C1;bad\\}"),"source names escaped as MText literals");
string clamped=PipeStakeMath.Label(v with{Clamped=true});Check(clamped.Contains("DIST TO PIPE END")&&clamped.Contains("BEYOND PIPE LIMITS"),"clamped values unmistakable");
Check(PipeStakeMath.Label(v with{Wall=null,Top=null}).Contains("TOP (OUTSIDE): UNKNOWN"),"unknown roof explicit");
Check(PipeStakeMath.Label(v with{Alignment=null,Station=null}).Contains("PIPE DIST: 803.32 ft from start"),"no alignment is not fake project station");
Check(PipeStakeMath.ReadText(()=>throw new InvalidOperationException("Part Family is invalid"))==null,"throwing catalog display getter is optional");
Check(PipeStakeMath.ReadThickness(()=>throw new InvalidOperationException("Part Family is invalid"))==null,"throwing thickness getter remains unknown");
Check(PipeStakeMath.ReadThickness(()=>0)==null,"zero native thickness unknown");
Near(PipeStakeMath.ReadThickness(()=>11.0/12)!.Value,11.0/12,"valid native thickness retained");
Check(PipeStakeMath.Material(null,"10 x 6 RCB",null)=="RCB","description fallback after invalid family");
Check(PipeStakeMath.Material(null,null,"CLV_RCP 30 inch")=="RCP","size fallback after invalid family");
Check(PipeStakeMath.Material(null,null,null).StartsWith("UNKNOWN"),"no metadata never guesses a material");
Check(PipeStakeMath.Material("CLV_C900","PVC",null)=="C900","C900 specification retained");
Check(PipeStakeMath.Material("CLV_PVC","replaced RCP",null)=="PVC","recognized valid family takes precedence over description");
try { PipeStakeMath.Required<double>(()=>throw new InvalidOperationException("Part Family is invalid"),"inside pipe height"); throw new Exception("required dimension silently skipped"); }
catch(InvalidOperationException ex) { Check(ex.Message.Contains("inside pipe height")&&ex.Message.Contains("Part Family is invalid"),"required getter error retains field and cause"); }
Console.WriteLine($"Passed {count} pipe stake math/label checks.");
